start=time.monotonic();cpu=time.process_time()
root=Path('/home/qq/local-llm/models');names=['Qwen3.8-Flash-Next-Uncensored-IQ4XS-NGQ4.gguf','qwen38-flash-next-mtp-Q4_K_M.gguf'];rows=[]
class Bound(Exception):pass
for name in names:
 p=root/name;before=p.stat();fd=os.open(p,os.O_RDONLY|getattr(os,'O_NOFOLLOW',0))
 try:b=os.read(fd,65536);after=os.fstat(fd)
 finally:os.close(fd)
 assert before.st_ino==after.st_ino and before.st_size==after.st_size and before.st_mtime_ns==after.st_mtime_ns
 pos=0
 def take(n):
  global pos
  if n<0 or pos+n>len(b):raise Bound('64KiB metadata header limit')
  out=b[pos:pos+n];pos+=n;return out
 def num(fmt):return struct.unpack('<'+fmt,take(struct.calcsize('<'+fmt)))[0]
 def string():
  n=num('Q')
  if n>65536:raise Bound('metadata string exceeds local header read')
  return take(n).decode('utf-8','replace')
 def val(t,depth=0):
  if depth>2:raise Bound('array nesting limit')
  fmt={0:'B',1:'b',2:'H',3:'h',4:'I',5:'i',6:'f',7:'?',10:'Q',11:'q',12:'d'}
  if t in fmt:return num(fmt[t])
  if t==8:return string()
  if t==9:
   sub=num('I');count=num('Q')
   if count>128:raise Bound('large array not read beyond metadata header')
   return [val(sub,depth+1) for _ in range(count)]
  raise Bound('unknown metadata type')
 out={'path':str(p),'header_bytes_read':len(b),'header_sha256':hashlib.sha256(b).hexdigest(),'file_bytes':before.st_size,'file_identity':{'device':before.st_dev,'inode':before.st_ino,'size':before.st_size,'mtime_ns':before.st_mtime_ns,'ctime_ns':before.st_ctime_ns},'metadata':{},'complete_payload_hashed':False,'model_loaded':False}
 try:
  assert take(4)==b'GGUF'
  out['version']=num('I');out['tensor_count']=num('Q');out['metadata_key_count']=num('Q')
  assert out['version'] in (2,3)
  for i in range(min(out['metadata_key_count'],256)):
   k=string();typ=num('I');v=val(typ)
   if k.startswith('general.') or k.endswith('.block_count') or k.endswith('.context_length') or k.endswith('.embedding_length'):
    out['metadata'][k]=v
   out['metadata_keys_parsed']=i+1
  out['metadata_complete']=out.get('metadata_keys_parsed',0)==out['metadata_key_count']
 except Bound as e:out['metadata_complete']=False;out['bounded_stop_reason']=str(e)
 rows.append(out)
print(json.dumps({'schema':'hepta.e3-known-gguf-header-readonly.v1','host':'ai395','scope':'fixed first 64KiB of each of two already observed model files only','files':rows,'total_file_bytes_read':sum(x['header_bytes_read'] for x in rows),'full_weight_hash_performed':False,'network_requests':0,'model_loads':0,'model_calls':0,'training_updates':0,'self_cpu_seconds':time.process_time()-cpu,'wall_seconds':time.monotonic()-start},sort_keys=True))
